package app.flow.player;
import android.content.*;import org.json.*;import java.net.*;import java.util.*;
/** Title/year matched public poster lookups, independent of the media server. */
final class MovieArt {
 static JSONObject lookup(Context c,String title,String year)throws Exception{if(title==null||title.length()>180||title.trim().isEmpty())throw new IllegalArgumentException();year=year!=null&&year.matches("(?:19|20)\\d{2}")?year:"";String key=MovieInfo.normal(title)+"|"+year;SharedPreferences cache=c.getSharedPreferences("online-artwork-v1",0);String old=cache.getString(key,null);long age=System.currentTimeMillis()-cache.getLong("checked:"+key,0);if(old!=null){JSONObject hit=new JSONObject(old);if(age<(hit.optBoolean("found")?7*86400000L:3600000L))return hit.put("cached",true);}JSONObject result=fetch(title,year);if(!result.optBoolean("found")&&age<CachePolicy.WEEK&&old!=null&&new JSONObject(old).optBoolean("found"))return new JSONObject(old).put("cached",true);SharedPreferences.Editor edit=cache.edit();if(cache.getAll().size()>800)edit.clear();edit.putString(key,result.toString()).putLong("checked:"+key,System.currentTimeMillis()).apply();return result;}
 static JSONObject imdb(JSONObject response,String title,String year)throws Exception{JSONArray items=response.optJSONArray("d");if(items==null)return null;String wanted=MovieInfo.normal(title);JSONObject chosen=null;double best=0;for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item==null||!item.optString("id").matches("tt[0-9]+"))continue;String type=item.optString("qid");if(!Arrays.asList("movie","tvSeries","tvMiniSeries","tvMovie").contains(type))continue;String name=MovieInfo.normal(item.optString("l"));if(!year.isEmpty()&&!year.equals(String.valueOf(item.optInt("y"))))continue;Set<String> a=new HashSet<>(Arrays.asList(wanted.split(" +"))),b=new HashSet<>(Arrays.asList(name.split(" +")));int overlap=0;for(String word:a)if(b.contains(word))overlap++;double score=2d*overlap/Math.max(1,a.size()+b.size());if(name.equals(wanted))score+=1;JSONObject image=item.optJSONObject("i");if(image==null)continue;String url=image.optString("imageUrl");if(!safeImage(url))continue;if(score>best&&score>=.9){best=score;chosen=new JSONObject().put("found",true).put("url",url).put("source","IMDb").put("title",item.optString("l")).put("year",item.optInt("y")).put("sourceURL","https://www.imdb.com/title/"+item.optString("id")+"/");}}return chosen;}
 static boolean safeImage(String url){try{URI u=new URI(url);String host=u.getHost();return "https".equals(u.getScheme())&&host!=null&&(host.equals("m.media-amazon.com")||host.equals("upload.wikimedia.org"));}catch(Exception e){return false;}}
 static JSONObject fetch(String title,String year)throws Exception{try{String query=URLEncoder.encode(title.trim().toLowerCase(Locale.ROOT),"UTF-8").replace("+","%20");JSONObject match=imdb(MovieInfo.get("https://v3.sg.media-imdb.com/suggestion/x/"+query+".json"),title,year);if(match!=null)return match;}catch(Exception ignored){}
  try{String props="&prop=extracts%7Cpageprops%7Cpageimages%7Cinfo&exintro=1&explaintext=1&exsentences=1&piprop=thumbnail&pithumbsize=600&inprop=url";String titles=title+"|"+title+" (film)"+(year.isEmpty()?"":"|"+title+" ("+year+" film)");JSONObject data=MovieInfo.get("https://en.wikipedia.org/w/api.php?action=query&format=json&redirects=1&titles="+MovieInfo.enc(titles)+props);JSONObject page=MovieInfo.best(data,title,year);if(page==null){data=MovieInfo.get("https://en.wikipedia.org/w/api.php?action=query&format=json&generator=search&gsrnamespace=0&gsrlimit=4&gsrsearch="+MovieInfo.enc(title+" "+year+" film")+props);page=MovieInfo.best(data,title,year);}if(page!=null&&page.optJSONObject("thumbnail")!=null){String image=page.getJSONObject("thumbnail").optString("source");if(safeImage(image))return new JSONObject().put("found",true).put("url",image).put("source","Wikipedia / Wikimedia").put("title",page.optString("title")).put("sourceURL",page.optString("fullurl"));}}catch(Exception ignored){}
  return new JSONObject().put("found",false).put("message","No confident online poster match is available.");
 }
}
